137	    ///
138	    /// The response isn't sent immediately. Instead, it's queued up in the main loop
139	    /// and checked for cancellation (each request must have exactly one response).
140	    pub(crate) fn respond<R>(&self, id: &RequestId, result: crate::server::Result<R>)
141	    where
142	        R: serde::Serialize,
143	    {
144	        let response = match result {
145	            Ok(res) => lsp_server::Response::new_ok(id.clone(), res),
146	            Err(crate::server::Error { code, error }) => {
147	                lsp_server::Response::new_err(id.clone(), code as i32, error.to_string())
148	            }
149	        };
150	
151	        self.main_loop_sender
152	            .send(Event::Action(Action::SendResponse(response)))
153	            .unwrap();
154	    }
