use lsp_types::{CodeAction, Url};

use crate::server::api::traits::{
    BackgroundRequestHandler, RequestHandler, RetriableRequestHandler,
};
use crate::session::SessionSnapshot;
use crate::session::client::Client;

pub(crate) struct CodeActionResolveRequestHandler;

impl RequestHandler for CodeActionResolveRequestHandler {
    type RequestType = CodeActionResolveRequest;
}

impl BackgroundRequestHandler for CodeActionResolveRequestHandler {
    fn run(
        _snapshot: &SessionSnapshot,
        _client: &Client,
        action: CodeAction,
    ) -> crate::server::Result<CodeAction> {
        // The `data` field of a code action carries the URL of the document it applies to. If it's
        // missing or can't be parsed as a URL, there's nothing to resolve, so return the code
        // action unchanged rather than failing the request.
        let Some(data) = &action.data else {
            return Ok(action);
        };
        if serde_json::from_value::<Url>(data.clone()).is_err() {
            return Ok(action);
        }

        // ty computes fully-resolved code actions (with their edits already populated) in the
        // `textDocument/codeAction` handler, so there's nothing further to resolve here.
        Ok(action)
    }
}

